  AND execution_status = 'RUNNING'
FOR SHARE

mapper.update:
UPDATE fin_ex_chat_run_t r
SET route_type = #{row.routeType},
    agent_code = #{row.agentCode},
    runtime_provider = #{row.runtimeProvider},
    runtime_session_id = #{row.runtimeSessionId},
    metadata_json = #{row.metadataJson},
    updated_at = #{row.updatedAt}
WHERE r.id = #{row.id}
  AND r.tenant_id = #{row.tenantId}
  AND r.user_id = #{row.userId}
  AND r.session_id = #{row.sessionId}
  AND r.status = 'RUNNING'
  AND EXISTS (
      SELECT 1
      FROM fin_ex_chat_run_execution_t e
      WHERE e.run_id = r.id
        AND e.tenant_id = r.tenant_id
        AND e.user_id = r.user_id
        AND e.session_id = r.session_id
        AND e.owner_instance_id = #{claim.ownerInstanceId}
        AND e.fencing_token = #{claim.fencingToken}
        AND e.execution_status = 'RUNNING'
  )

UPDATE fin_ex_chat_run_t
SET status = 'CANCELLING',
    cancel_reason = #{reason},
    updated_at = #{requestedAt}
WHERE id = #{runId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND status = 'RUNNING'

UPDATE fin_ex_chat_run_t r
SET updated_at = CURRENT_TIMESTAMP
WHERE r.id = #{runId}
  AND r.tenant_id = #{tenantId}
  AND r.user_id = #{userId}
  AND r.session_id = #{sessionId}
  AND r.status = 'RUNNING'
  AND EXISTS (
      SELECT 1
      FROM fin_ex_chat_run_execution_t e
      WHERE e.run_id = r.id
        AND e.tenant_id = r.tenant_id
        AND e.user_id = r.user_id
        AND e.session_id = r.session_id
        AND e.owner_instance_id = #{ownerInstanceId}
        AND e.fencing_token = #{fencingToken}
        AND e.execution_status = 'RUNNING'
  )

UPDATE fin_ex_chat_run_t
SET last_seq = #{sequence},
    cancel_reason = COALESCE(#{cancelReason}, cancel_reason),
    finished_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE id = #{runId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND status = #{terminalStatus}

